<div class="page-title"><div><em>CUSTOMER MANAGEMENT</em><h1>Create customer</h1><p>Create a secure customer profile and primary bank account.</p></div><a class="outline" href="<?=site_url('admin/customers')?>">Cancel</a></div><section class="panel form-panel narrow"><?=form_open('admin/customers/create')?><div class="form-grid"><div><label>First name</label><input name="first_name" required></div><div><label>Last name</label><input name="last_name" required></div><div><label>Username</label><input name="username" required></div><div><label>Email address</label><input name="email" type="email" required></div><div><label>Phone number</label><input name="phone"></div><div><label>Country</label><input name="country" value="United States"></div><div><label>Opening balance</label><input name="opening_balance" type="number" min="0" step="0.01" value="0" required></div><div><label>Temporary password</label><input name="password" type="password" minlength="8" required></div></div><button class="btn">Create customer account</button></form></section>
